        source.startsWith("jrt:/") -> "jrt:/ (the JDK's modules file, parsed now)"
        source.startsWith("file:") -> "file: (your classes and JARs, kotlin-stdlib too)"
        else -> "other (hidden classes: lambdas, method handles)"
    }
}

